(lib.TimePop = function(mode,startPosition,loop,reversed) {
if (loop == null) { loop = true; }
if (reversed == null) { reversed = false; }
	var props = new Object();
	props.mode = mode;
	props.startPosition = startPosition;
	props.labels = {};
	props.loop = loop;
	props.reversed = reversed;
	cjs.MovieClip.apply(this,[props]);

	this.isSingleFrame = false;
	// timeline functions:
	this.frame_0 = function() {
		if(this.isSingleFrame) {
			return;
		}
		if(this.totalFrames == 1) {
			this.isSingleFrame = true;
		}
		this.stop();
		var ts = this;
		createjs.Tween.get(ts, {
			useTicks: true
		}).wait(1).call(updateTexts);
		function updateTexts() {
			var tw = 500;
			var th = 290;
			lg.translate("timTxt", ts.txt,{bold:false});
			var r = ts.txt.getBounds();
			var s1 = tw / r.width;
			var s2 = th / r.height;
			var fset = s1 < s2 ? s1 : s2;
			if (fset < 1) {
				lg.translate("timTxt", ts.txt, {
					bold:false,
					fw: fset
				});
			}
			var h = ts.txt.getMeasuredHeight();
			ts.txt.y += (th - h) / 2;
			lg.translate("tfT", ts.ttl.txt, {
				upper: true
			});
			lg.translate("tfT", ts.ttl.txt1, {
				upper: true
			});
			lg.scaleTextBox(ts.ttl,575);
		}
	}

	// actions tween:
	this.timeline.addTween(cjs.Tween.get(this).call(this.frame_0).wait(1));

	// Bitmap_2
	this.noTime = new lib.seewq2();
	this.noTime.name = "noTime";
	this.noTime.setTransform(561.65,549.9,0.85,0.85);
	new cjs.ButtonHelper(this.noTime, 0, 1, 2, false, new lib.seewq2(), 3);

	this.yesTime = new lib.saww1();
	this.yesTime.name = "yesTime";
	this.yesTime.setTransform(723.1,549.9,0.85,0.85);
	new cjs.ButtonHelper(this.yesTime, 0, 1, 2, false, new lib.saww1(), 3);

	this.txt = new cjs.Text("Rewarded Ad is not loaded or some network interruption happened. Please try later.", "40px 'Passion One'", "#99FFCC");
	this.txt.name = "txt";
	this.txt.textAlign = "center";
	this.txt.lineHeight = 46;
	this.txt.lineWidth = 496;
	this.txt.parent = this;
	this.txt.setTransform(634.9,210.1);

	this.ttl = new lib.AM();
	this.ttl.name = "ttl";
	this.ttl.setTransform(635,161.4);

	this.instance = new lib.JC();
	this.instance.setTransform(350,81,0.8095,0.8095);

	this.instance_1 = new lib.IX();
	this.instance_1.setTransform(-69,-41,14.0798,14.1426);

	this.timeline.addTween(cjs.Tween.get({}).to({state:[{t:this.instance_1},{t:this.instance},{t:this.ttl},{t:this.txt},{t:this.yesTime},{t:this.noTime}]}).wait(1));

	this._renderFirstFrame();

}).prototype = getMCSymbolPrototype(lib.TimePop, new cjs.Rectangle(-69,-41,1408,792), null);


