		lg.codes = [];
		for(var key in lg.languages) {
			lg.codes.push(key);
		}
		function getUserBrowserLanguage() {
			if(caller(2, "langCode") != "en") {
				return caller(2, "langCode");
			}
			const userLanguage = window.navigator.language || window.navigator.userLanguage;
			var bl = userLanguage.split('-')[0];
			if(lg.codes.indexOf(bl) >= 0) {
				return bl;
			} else {
				return "en";
			}
		}
		lg.lang = getUserBrowserLanguage();
		caller(1, "langCode", lg.lang);
		
